struct slice
        {
            jsoncons::optional<int64_t> start_;
            jsoncons::optional<int64_t> stop_;
            int64_t step_;

            slice()
                : step_(1)
            {
            }

            slice(const jsoncons::optional<int64_t>& start, const jsoncons::optional<int64_t>& end, int64_t step) 
                : start_(start), stop_(end), step_(step)
            {
            }

            slice(const slice& other) = default;

            slice(slice&& other) = default;

            slice& operator=(const slice& other) = default;

            slice& operator=(slice&& other) = default;

            ~slice() = default;

            int64_t get_start(std::size_t size) const
            {
                if (start_)
                {
                    auto len = *start_ >= 0 ? *start_ : (static_cast<int64_t>(size) + *start_);
                    return len <= static_cast<int64_t>(size) ? len : static_cast<int64_t>(size);
                }
                else
                {
                    if (step_ >= 0)
                    {
                        return 0;
                    }
                    else 
                    {
                        return static_cast<int64_t>(size);
                    }
                }
            }

            int64_t get_stop(std::size_t size) const
            {
                if (stop_)
                {
                    auto len = *stop_ >= 0 ? *stop_ : (static_cast<int64_t>(size) + *stop_);
                    return len <= static_cast<int64_t>(size) ? len : static_cast<int64_t>(size);
                }
                else
                {
                    return step_ >= 0 ? static_cast<int64_t>(size) : -1;
                }
            }

            int64_t step() const
            {
                return step_; // Allow negative
            }
        };

namespace jsoncons { 
namespace jsonpointer {

    namespace detail {

    enum class pointer_state 
    {
        start,
        escaped,
        new_token,
        part
    };

    } // namespace detail

template <typename CharT>
class basic_json_pointer
{
public:
    using char_type = CharT;
    using string_type = std::basic_string<char_type>;
    using string_view_type = jsoncons::basic_string_view<char_type>;
    using const_iterator = typename std::vector<string_type>::const_iterator;
    using iterator = const_iterator;
    using const_reverse_iterator = typename std::vector<string_type>::const_reverse_iterator;
    using reverse_iterator = const_reverse_iterator;
private:
    std::vector<string_type> tokens_;
public:
    basic_json_pointer() {}
    basic_json_pointer(const std::vector<string_type>& tokens) : tokens_(tokens) {}
    basic_json_pointer(std::vector<string_type>&& tokens) : tokens_(std::move(tokens)) {}
    explicit basic_json_pointer(const string_view_type& s)
    {
        std::error_code ec;
        auto jp = parse(s, ec);
        if (JSONCONS_UNLIKELY(ec))
        {
            JSONCONS_THROW(jsonpointer_error(ec));
        }
        tokens_ = std::move(jp.tokens_);
    }
    explicit basic_json_pointer(const string_view_type& s, std::error_code& ec)
    {
        auto jp = parse(s, ec);
        if (!ec)
        {
            tokens_ = std::move(jp.tokens_);
        }
    }
    basic_json_pointer(const basic_json_pointer&) = default;
    basic_json_pointer(basic_json_pointer&&) = default;

    static basic_json_pointer parse(const string_view_type& input, std::error_code& ec)
    {
        std::vector<string_type> tokens;
        if (input.empty())
        {
            return basic_json_pointer<CharT>();
        }
        const char_type* p = input.data();
        const char_type* pend = input.data() + input.size();
        string_type unescaped;
        auto state = jsonpointer::detail::pointer_state::start;
        string_type buffer;
        while (p < pend)
        {
            switch (state)
            {
                case jsonpointer::detail::pointer_state::start: 
                    switch (*p)
                    {
                        case '/':
                            state = jsonpointer::detail::pointer_state::new_token;
                            break;
                        default:
                            ec = jsonpointer_errc::expected_slash;
                            return basic_json_pointer();
                    };
                    break;
                case jsonpointer::detail::pointer_state::part:
                    state = jsonpointer::detail::pointer_state::new_token; 
                    JSONCONS_FALLTHROUGH;
                case jsonpointer::detail::pointer_state::new_token: 
                    switch (*p)
                    {
                        case '/':
                            tokens.push_back(buffer);
                            buffer.clear();
                            state = jsonpointer::detail::pointer_state::part; 
                            break;
                        case '~':
                            state = jsonpointer::detail::pointer_state::escaped;
                            break;
                        default:
                            buffer.push_back(*p);
                            break;
                    };
                    break;
                case jsonpointer::detail::pointer_state::escaped: 
                    switch (*p)
                    {
                        case '0':
                            buffer.push_back('~');
                            state = jsonpointer::detail::pointer_state::new_token;
                            break;
                        case '1':
                            buffer.push_back('/');
                            state = jsonpointer::detail::pointer_state::new_token;
                            break;
                        default:
                            ec = jsonpointer_errc::expected_0_or_1;
                            return basic_json_pointer();
                    };
                    break;
            }
            ++p;
        }
        if (state == jsonpointer::detail::pointer_state::escaped)
        {
            ec = jsonpointer_errc::expected_0_or_1;
            return basic_json_pointer();
        }
        if (state == jsonpointer::detail::pointer_state::new_token || state == jsonpointer::detail::pointer_state::part)
        {
            tokens.push_back(buffer);
        }
        return basic_json_pointer(tokens);
    }

    const std::vector<string_type>& tokens() const { return tokens_; }
    std::vector<string_type>& tokens() { return tokens_; }
    const string_type& back() const { return tokens_.back(); }

    basic_json_pointer& operator=(const basic_json_pointer&) = default;
    basic_json_pointer& operator=(basic_json_pointer&&) = default;

    void clear() { tokens_.clear(); }

    basic_json_pointer& append(const string_type& s) { tokens_.push_back(s); return *this; }

    template <typename IntegerType>
    typename std::enable_if<ext_traits::is_integer<IntegerType>::value, basic_json_pointer&>::type
    append(IntegerType val)
    {
        string_type s;
        jsoncons::from_integer(val, s);
        tokens_.push_back(s);
        return *this;
    }

    basic_json_pointer& operator/=(const string_type& s) { tokens_.push_back(s); return *this; }

    template <typename IntegerType>
    typename std::enable_if<ext_traits::is_integer<IntegerType>::value, basic_json_pointer&>::type
    operator/=(IntegerType val)
    {
        string_type s;
        jsoncons::from_integer(val, s);
        tokens_.push_back(s);
        return *this;
    }

    basic_json_pointer& operator+=(const basic_json_pointer& p)
    {
        for (const auto& s : p.tokens_) { tokens_.push_back(s); }
        return *this;
    }

    bool empty() const { return tokens_.empty(); }

    string_type string() const { return to_string(); }

    string_type to_string() const
    {
        string_type buffer;
        for (const auto& token : tokens_)
        {
            buffer.push_back('/');
            for (auto c : token)
            {
                switch (c)
                {
                    case '~': buffer.push_back('~'); buffer.push_back('0'); break;
                    case '/': buffer.push_back('~'); buffer.push_back('1'); break;
                    default: buffer.push_back(c); break;
                }
            }
        }
        return buffer;
    }

    iterator begin() const { return tokens_.begin(); }
    iterator end() const { return tokens_.end(); }
    reverse_iterator rbegin() const { return tokens_.rbegin(); }
    reverse_iterator rend() const { return tokens_.rend(); }

    friend basic_json_pointer<CharT> operator/(const basic_json_pointer<CharT>& lhs, const string_type& rhs)
    { basic_json_pointer<CharT> p(lhs); p /= rhs; return p; }

    friend basic_json_pointer<CharT> operator+( const basic_json_pointer<CharT>& lhs, const basic_json_pointer<CharT>& rhs )
    { basic_json_pointer<CharT> p(lhs); p += rhs; return p; }

    friend bool operator==( const basic_json_pointer& lhs, const basic_json_pointer& rhs )
    { return lhs.tokens_ == rhs.tokens_; }
    friend bool operator!=( const basic_json_pointer& lhs, const basic_json_pointer& rhs )
    { return lhs.tokens_ != rhs.tokens_; }
    friend bool operator<(const basic_json_pointer& lhs, const basic_json_pointer& rhs)
    { return lhs.tokens_ < rhs.tokens_; }
    friend bool operator<=(const basic_json_pointer& lhs, const basic_json_pointer& rhs)
    { return lhs.tokens_ <= rhs.tokens_; }
    friend bool operator>(const basic_json_pointer& lhs, const basic_json_pointer& rhs)
    { return lhs.tokens_ > rhs.tokens_; }
    friend bool operator>=(const basic_json_pointer& lhs, const basic_json_pointer& rhs)
    { return lhs.tokens_ >= rhs.tokens_; }

    friend std::basic_ostream<CharT>& operator<<(std::basic_ostream<CharT>& os, const basic_json_pointer<CharT>& p )
    { os << p.to_string(); return os; }
};

