import random
import json
import string
from typing import List

# Generator for valid and interesting JMESPath expressions.
# These are targeted to exercise jsoncons::jmespath::search and make_expression.
# We keep expressions diverse but valid per JMESPath grammar to avoid immediate exceptions.

IDENT_START = string.ascii_letters + "_"
IDENT_PART = IDENT_START + string.digits + "-"

FUNCTIONS_NOARG = [
    "to_string", "to_number", "type", "length", "keys", "values", "abs", "not_null"
]
FUNCTIONS_ONEARG = [
    "length", "type", "to_string", "to_number", "reverse", "sort", "avg", "sum", "max", "min"
]
FUNCTIONS_TWOARG = [
    "contains", "starts_with", "ends_with", "join"
]
FUNCTIONS_VARARG = [
    "concat", "coalesce", "merge"
]

LITERALS = [
    "null", "true", "false",
]

def rnd_ident(rng: random.Random, min_len=1, max_len=10) -> str:
    l = rng.randint(min_len, max_len)
    s = rng.choice(IDENT_START)
    for _ in range(l - 1):
        s += rng.choice(IDENT_PART)
    return s

def rnd_string(rng: random.Random, min_len=0, max_len=12) -> str:
    # JSON string literal with common escapables
    chars = string.ascii_letters + string.digits + " _-:/._~"
    l = rng.randint(min_len, max_len)
    s = ''.join(rng.choice(chars) for _ in range(l))
    # occasionally include '~' and '/' to interact with pointer escaping when used as keys
    if rng.random() < 0.3:
        s += rng.choice(["~", "/"])
    return json.dumps(s)

def rnd_number(rng: random.Random) -> str:
    if rng.random() < 0.3:
        return str(rng.randint(-1000, 1000))
    # float
    val = rng.uniform(-1e3, 1e3)
    return ("%.3f" % val).rstrip("0").rstrip(".")

def rnd_literal(rng: random.Random) -> str:
    choice = rng.random()
    if choice < 0.34:
        return rnd_number(rng)
    elif choice < 0.67:
        return rnd_string(rng)
    else:
        return rng.choice(LITERALS)

def path_segment(rng: random.Random) -> str:
    # Choose between simple identifier, quoted identifier, or array index
    t = rng.random()
    if t < 0.55:
        return rnd_ident(rng)
    elif t < 0.75:
        # bracket-quoted identifier
        return f"['{rnd_ident(rng)}']"
    else:
        return f"[{rng.randint(0, 5)}]"

def projection(rng: random.Random, base: str) -> str:
    # [], |, [].foo, [*].foo, [].[a,b]
    choice = rng.random()
    if choice < 0.25:
        return base + "[]"
    elif choice < 0.5:
        return base + "[]." + path_segment(rng)
    elif choice < 0.75:
        a = path_segment(rng)
        b = path_segment(rng)
        return base + f"[].[{a},{b}]"
    else:
        return base + "[*]." + path_segment(rng)

def filter_expr(rng: random.Random, base: str) -> str:
    # base[? expr ] where expr compares fields
    left = rnd_ident(rng)
    op = rng.choice(["==", "!=", ">=", "<=", ">", "<"])
    right = rnd_literal(rng)
    return f"{base}[? {left} {op} {right} ]"

def function_call(rng: random.Random, expr: str) -> str:
    r = rng.random()
    if r < 0.25:
        fn = rng.choice(FUNCTIONS_NOARG)
        return f"{fn}()"
    elif r < 0.55:
        fn = rng.choice(FUNCTIONS_ONEARG)
        return f"{fn}({expr})"
    elif r < 0.85:
        fn = rng.choice(FUNCTIONS_TWOARG)
        other = expr_or_literal(rng)
        return f"{fn}({expr}, {other})"
    else:
        fn = rng.choice(FUNCTIONS_VARARG)
        args = [expr] + [expr_or_literal(rng) for _ in range(rng.randint(1, 3))]
        return f"{fn}({', '.join(args)})"

def expr_or_literal(rng: random.Random) -> str:
    if rng.random() < 0.5:
        return rnd_literal(rng)
    else:
        return subexpr(rng, depth=0)

def pipe_chain(rng: random.Random, left: str) -> str:
    right = subexpr(rng, depth=0)
    return f"{left} | {right}"

def subexpr(rng: random.Random, depth: int) -> str:
    # Build a sub-expression with limited depth for validity
    depth = depth + 1
    # Base
    base = rng.choice(["@", rnd_ident(rng)])
    # extend with path segments
    for _ in range(rng.randint(0, 2)):
        if rng.random() < 0.6:
            base += "." + path_segment(rng)
        else:
            base = projection(rng, base)
    # optional filter
    if rng.random() < 0.4:
        base = filter_expr(rng, base)
    # optional function on top
    if rng.random() < 0.5:
        base = function_call(rng, base)
    # optional comparison
    if rng.random() < 0.35:
        rhs = expr_or_literal(rng)
        op = rng.choice(["==", "!=", ">=", "<=", ">", "<", "&&", "||"])
        base = f"{base} {op} {rhs}"
    # optional pipe
    if rng.random() < 0.25 and depth < 3:
        base = pipe_chain(rng, base)
    return base

def top_level(rng: random.Random) -> str:
    choice = rng.random()
    if choice < 0.25:
        # multi-select list
        parts = [subexpr(rng, 0) for _ in range(rng.randint(2, 4))]
        return "[" + ", ".join(parts) + "]"
    elif choice < 0.5:
        # multi-select hash
        pairs = []
        for _ in range(rng.randint(2, 4)):
            key = rnd_ident(rng)
            val = subexpr(rng, 0)
            pairs.append(f"{key}: {val}")
        return "{" + ", ".join(pairs) + "}"
    elif choice < 0.7:
        # bracket specifier from root
        return projection(rng, "[]")
    else:
        # plain expression
        return subexpr(rng, 0)

def make_expression(rng: random.Random, target_size: int = 128) -> str:
    # Compose 1-3 expressions possibly joined by pipes to hit parser paths
    parts = [top_level(rng) for _ in range(rng.randint(1, 2))]
    expr = parts[0] if parts else "@"
    if len(parts) > 1:
        for p in parts[1:]:
            expr += " | " + p
    # Ensure modest size
    if len(expr) > target_size:
        expr = expr[:target_size]
    return expr

def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    # Randomly choose one of several expression themes
    theme = rng.randint(0, 6)
    if theme == 0:
        # Simple dotted path with projection and filter
        expr = filter_expr(rng, projection(rng, rnd_ident(rng)))
    elif theme == 1:
        # Function on whole document and pipe
        left = function_call(rng, "@")
        expr = pipe_chain(rng, left)
    elif theme == 2:
        # Multi-select list
        expr = top_level(rng)
    elif theme == 3:
        # Equality comparison between field and literal
        expr = f"{rnd_ident(rng)} == {rnd_literal(rng)}"
    elif theme == 4:
        # Nested projections
        base = rnd_ident(rng)
        for _ in range(rng.randint(1, 3)):
            base = projection(rng, base)
        expr = base
    elif theme == 5:
        # Multi-select hash
        expr = top_level(rng)
    else:
        expr = make_expression(rng)

    # Bound size as per fuzz stub expectations (<= 512); we target <= 512, smaller preferred
    expr = expr[:512]
    return expr.encode('utf-8')

import random
import string
from typing import List

# Target data type: JSON Pointer token (unescaped single segment)
# We need to provide initial buffers for FUZZ_PARAM_STR and FUZZ_PARAM_FILENAME used by stubs.
# Stubs consume strings as tokens and general strings to be escaped; unflatten builds keys by
# prepending '/' and escaping, so supplying diverse unescaped tokens (including characters that
# need escaping '~' and '/') will exercise escaping and pointer building.
#
# Strategy:
# - Generate a single UTF-8 byte sequence representing a plausible token. Since the fuzzers use
#   std::string and jsoncons expects char-based strings, we stick to UTF-8 bytes.
# - Include a mix of:
#   - simple alphanumerics
#   - tokens containing '~' and '/' to exercise escape to ~0 and ~1
#   - numeric strings (for array indices)
#   - special cases: empty token, repeated separators, long tokens within limit, unicode bytes
#   - composite tokens joined by random content; however each FUZZ_PARAM_STR is one token, so we
#     do not include leading '/'.
# - Ensure size <= 4096 bytes.
# - Seeded randomness.

SAFE_ASCII = string.ascii_letters + string.digits + "_-.:@"

UNICODE_SAMPLES = [
    "αβγ", "Привет", "こんにちは", "😀", "éàç", "Δ/Θ~", "ключ", "العربية", "हिन्दी",
    "路径", "π/ρ~σ", "тест~0/1", "mañana", "straße", "δοκιμή"
]

NUMERIC_STRINGS = [
    "0", "1", "2", "9", "10", "42", "99", "123", "2147483647", "9223372036854775807"
]

EDGE_TOKENS = [
    "",  # empty token (valid between // in a full pointer, still useful as token input)
    "~",  # requires escaping -> ~0
    "/",  # requires escaping -> ~1
    "~/", # both need escaping
    "~~", "//", "~1", "~0",  # test pass-through vs re-escape logic
    "-",  # special meaning for arrays when used as last token in add
    "00", "01",  # numeric-looking with leading zeros
]

def rand_choice(r: random.Random, seq: List[str]) -> str:
    return seq[r.randrange(len(seq))]

def make_alnum_token(r: random.Random, min_len=1, max_len=32) -> str:
    n = r.randint(min_len, max_len)
    return ''.join(r.choice(SAFE_ASCII) for _ in range(n))

def make_mixed_token(r: random.Random) -> str:
    # Build a token mixing safe ascii with occasional '~' and '/'
    n = r.randint(1, 48)
    pieces = []
    for _ in range(n):
        t = r.random()
        if t < 0.12:
            pieces.append('~')
        elif t < 0.24:
            pieces.append('/')
        elif t < 0.30:
            pieces.append(rand_choice(r, ['~0','~1']))
        else:
            pieces.append(r.choice(SAFE_ASCII))
    return ''.join(pieces)

def make_unicode_token(r: random.Random) -> str:
    base = rand_choice(r, UNICODE_SAMPLES)
    # Optionally mix in escape-relevant chars
    if r.random() < 0.6:
        insert_chars = ['~', '/', '-', r.choice(SAFE_ASCII)]
        # insert at random positions
        for ch in insert_chars:
            pos = r.randint(0, len(base))
            base = base[:pos] + ch + base[pos:]
    # Limit length
    if len(base) > 128:
        base = base[:128]
    return base

def make_numeric_like(r: random.Random) -> str:
    if r.random() < 0.5:
        return rand_choice(r, NUMERIC_STRINGS)
    # random length numeric with possible leading zeros
    n = r.randint(1, 8)
    if r.random() < 0.3:
        # add leading zeros
        lead = '0' * r.randint(1, 3)
        digits = ''.join(r.choice(string.digits) for _ in range(max(1, n- len(lead))))
        return lead + digits
    else:
        return ''.join(r.choice(string.digits) for _ in range(n))

def make_edge_token(r: random.Random) -> str:
    return rand_choice(r, EDGE_TOKENS)

def choose_token(r: random.Random) -> str:
    # Weighted selection of token generators
    choice = r.random()
    if choice < 0.20:
        return make_edge_token(r)
    elif choice < 0.40:
        return make_numeric_like(r)
    elif choice < 0.65:
        return make_alnum_token(r)
    elif choice < 0.85:
        return make_mixed_token(r)
    else:
        return make_unicode_token(r)

def ensure_size_limit(b: bytes, limit: int = 4096) -> bytes:
    if len(b) <= limit:
        return b
    # Trim to limit without breaking UTF-8 (best effort)
    trimmed = b[:limit]
    # Ensure valid UTF-8 termination by backing up within last up to 3 bytes
    for back in range(0, 4):
        try:
            trimmed_valid = trimmed[:-back] if back else trimmed
            trimmed_valid.decode('utf-8')
            return trimmed_valid
        except UnicodeDecodeError:
            continue
    # Fallback to stripping non-ASCII tail
    return bytes(ch for ch in trimmed if ch < 128)[:limit]

def generate(seed: int) -> bytes:
    r = random.Random(seed)
    # Compose 1 to 3 tokens separated by newlines to feed multiple FUZZ_PARAM_STR calls
    # Many fuzz harnesses read buffers sequentially; providing multiple lines gives variety.
    count = r.randint(1, 3)
    tokens = []
    for _ in range(count):
        tok = choose_token(r)
        tokens.append(tok)
    payload = "\n".join(tokens)
    # Occasionally include additional cases concatenated to exercise longer inputs
    if r.random() < 0.3:
        payload += "\n" + make_mixed_token(r)
    if r.random() < 0.2:
        payload += "\n" + make_unicode_token(r)
    b = payload.encode('utf-8', errors='strict')
    return ensure_size_limit(b)
